#!/usr/bin/env bash
#
# Capture the SASS of every GEMM ladder rung into experiments/sass/.
#
# The captures are evidence and they are committed, the same way the ncu text
# pages are. What a kernel compiled to is a compile time fact: it needs no GPU,
# no locked clocks and no measurement protocol, so it is the one kind of number
# in this repository that can be regenerated by anyone with the toolkit and
# compared byte for byte. scripts/sass_diff.py turns that into a gate.
#
# Usage:
#   benchmarks/capture_sass.sh                       capture every rung
#   benchmarks/capture_sass.sh --rung mma_opt        capture one rung
#   benchmarks/capture_sass.sh --rung mma_opt --stdout   write it to stdout
#   benchmarks/capture_sass.sh --list                print the rung names
#
# Options:
#   --build-dir DIR   where the objects are (default: build, or CKL_BUILD_DIR)
#   --out-dir DIR     where the .sass files go (default: experiments/sass)
#   --arch SM         which ELF section to read (default: sm_120)
#
# Normalization, which is what makes a capture comparable across rebuilds and
# across machines. Six rules, applied in this order:
#
#   1. One architecture. A multiarch build carries the same kernel once per
#      target, so cuobjdump is asked for a single ELF section by --arch.
#   2. One kernel per block. Everything before the requested Function line and
#      everything after the next one is dropped, which also drops the fatbin
#      header, the ptx section and the identifier line holding an absolute
#      source path that differs on every machine.
#   3. The anonymous namespace module hash is folded to a fixed token. nvcc
#      builds it from the file name and a content hash, so a kernel in an
#      unnamed namespace would otherwise change name on any edit to its
#      translation unit, and the diff would report a rename rather than the
#      instruction that moved.
#   4. The instruction address column, /*0410*/, is dropped. It shifts every
#      later line when one instruction is added anywhere earlier.
#   5. The encoded instruction words, /* 0x000fc40000000f00 */, are dropped,
#      along with the continuation lines that carry nothing else. They are the
#      same information as the mnemonic plus the scheduling control bits, and
#      the control bits churn without the instruction stream changing.
#   6. .headerflags is dropped, and runs of whitespace are squeezed to one
#      space. cuobjdump's column alignment depends on the widest operand in the
#      kernel, so an unrelated edit reflows the whole file.
#
# What survives is the instruction text and its operands, in order, with the
# branch labels intact. That is strong enough that rebuilding an unchanged tree
# is a clean pass and weak enough that one changed instruction fails.

set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
build_dir="${CKL_BUILD_DIR:-${repo_root}/build}"
out_dir="${repo_root}/experiments/sass"
arch="sm_120"
want_rung=""
to_stdout=0
list_only=0

while [ $# -gt 0 ]; do
    case "$1" in
        --build-dir) build_dir="$2"; shift 2 ;;
        --out-dir) out_dir="$2"; shift 2 ;;
        --arch) arch="$2"; shift 2 ;;
        --rung) want_rung="$2"; shift 2 ;;
        --stdout) to_stdout=1; shift ;;
        --list) list_only=1; shift ;;
        -h|--help) sed -n '2,48p' "${BASH_SOURCE[0]}"; exit 0 ;;
        *) echo "capture_sass.sh: unknown option $1" >&2; exit 2 ;;
    esac
done

# The ladder, rung by rung. Each entry is
#
#   <rung name>|<object under the ckl_gemm object directory>:<mangled name substring>
#
# and a rung may carry several object and pattern pairs separated by a semicolon
# when more than one kernel is what the rung is. The patterns are substrings of
# the mangled name after rule 3 has folded the module hash, chosen to name one
# instantiation and not its neighbours: ILb0EE is the plain kernel and ILb1EE
# the fused or tail predicated one, and the TileShape integers pick the tile.
#
# Two things deliberately have no rung of their own. The split-K mainloop is the
# tile family kernel with a partials pointer, already captured as
# tile_128x128x32, so the split-K rung is the fixup pass that is the only code
# split-K adds. And the CUTLASS scale kernel that serves an empty contraction is
# a memory bound epilogue, not part of the reference line's mainloop.
rungs=(
    "naive|gemm_naive.cu.o:gemm_naive_kernel"
    "tiled|gemm_tiled.cu.o:gemm_tiled_kernel"
    "register|gemm_register.cu.o:gemm_register_kernel"
    "cp_async|gemm_cp_async.cu.o:gemm_cp_async_kernel"
    "wmma_fp16|gemm_wmma_fp16.cu.o:wmma_gemm_kernelI6__halfE"
    "wmma_bf16|gemm_wmma_bf16.cu.o:wmma_gemm_kernelI13__nv_bfloat16E"
    "mma_ptx|gemm_mma_ptx.cu.o:gemm_mma_ptx_kernel"
    "mma_ldm|gemm_mma_ldmatrix.cu.o:gemm_mma_ldmatrix_kernel"
    "mma_opt|gemm_mma_opt.cu.o:gemm_mma_opt_kernelILb0EE"
    "mma_opt_bias|gemm_mma_opt.cu.o:gemm_mma_opt_kernelILb1EE"
    "tile_128x128x32|gemm_tile_family.cu.o:TileShapeILi128ELi128ELi32ELi2ELi4EEELb0EE"
    "tile_128x256x32|gemm_tile_family.cu.o:TileShapeILi128ELi256ELi32ELi2ELi8EEELb0EE"
    "tile_256x128x32|gemm_tile_family.cu.o:TileShapeILi256ELi128ELi32ELi4ELi4EEELb0EE"
    "tile_128x64x64|gemm_tile_family.cu.o:TileShapeILi128ELi64ELi64ELi2ELi2EEELb0EE"
    "tile_64x128x64|gemm_tile_family.cu.o:TileShapeILi64ELi128ELi64ELi1ELi4EEELb0EE"
    "tile_128x128x64|gemm_tile_family.cu.o:TileShapeILi128ELi128ELi64ELi2ELi4EEELb0EE"
    "splitk|gemm_splitk.cu.o:splitk_fixup_kernel"
    "streamk|gemm_streamk.cu.o:streamk_kernelINS_6detail9TileShapeILi128ELi128ELi32ELi2ELi4EEELb0EE"
    "cutlass|gemm_cutlass_ref.cu.o:cutlass7Kernel2"
)

if [ "${list_only}" -eq 1 ]; then
    for entry in "${rungs[@]}"; do
        echo "${entry%%|*}"
    done
    exit 0
fi

object_dir="${build_dir}/src/gemm/CMakeFiles/ckl_gemm.dir"
if [ ! -d "${object_dir}" ]; then
    echo "capture_sass.sh: no object directory at ${object_dir}." >&2
    echo "Build first, or point --build-dir at a build tree." >&2
    exit 1
fi

if ! command -v cuobjdump >/dev/null 2>&1; then
    echo "capture_sass.sh: cuobjdump is not on PATH; it ships with the CUDA Toolkit." >&2
    exit 1
fi

toolkit="$(nvcc --version 2>/dev/null | sed -nE 's/.*release [0-9.]+, V([0-9.]+).*/\1/p')"
if [ -z "${toolkit}" ]; then
    toolkit="unknown"
fi

# Rules 2 to 6. Reads one cuobjdump dump on stdin, writes the block for the one
# kernel whose raw mangled name contains $pattern.
#
# The pattern is matched against the raw name and the fold of rule 3 is applied
# only to what gets printed, so a rung is selected by what nvcc actually emitted
# and the committed file still carries a stable name. nvcc spells an unnamed
# namespace as
#
#   <length>_GLOBAL__N__<8 hex>_<digits>_<file name>_<8 hex>
#
# where both hashes come from the translation unit, so the whole run from the
# length prefix to the second hash is what has to go.
extract_and_normalize() {
    local pattern="$1"
    awk -v pat="${pattern}" '
        function fold(n,    head, rest) {
            if (match(n, /_GLOBAL__N__[0-9a-f]{8}_[0-9]+_/) == 0) {
                return n
            }
            head = substr(n, 1, RSTART - 1)
            sub(/[0-9]+$/, "", head)          # the length prefix of the folded name
            rest = substr(n, RSTART + RLENGTH)
            if (match(rest, /_[0-9a-f]{8}/) > 0) {
                rest = substr(rest, RSTART + RLENGTH)
            }
            return head "_GLOBAL__N_" rest
        }
        /Function : / {
            name = $0
            sub(/^.*Function : /, "", name)
            keep = (index(name, pat) > 0)
            if (keep) { print "Function : " fold(name) }
            next
        }
        !keep { next }
        /\.headerflags/ { next }
        {
            line = $0
            gsub(/\/\*[0-9a-f]{4}\*\//, "", line)     # rule 4, the address column
            gsub(/\/\*[^*]*\*\//, "", line)           # rule 5, the encoded words
            gsub(/[ \t]+/, " ", line)                 # rule 6, the alignment padding
            sub(/^ /, "", line)
            sub(/ $/, "", line)
            if (line != "") { print line }
        }
    '
}

capture_one() {
    local name="$1"
    local spec="$2"
    local body=""
    local pair object pattern block

    # A rung may name several object and pattern pairs.
    local IFS=';'
    for pair in ${spec}; do
        object="${pair%%:*}"
        pattern="${pair#*:}"
        if [ ! -f "${object_dir}/${object}" ]; then
            echo "capture_sass.sh: ${name}: no object ${object} in ${object_dir}" >&2
            return 1
        fi
        block="$(cuobjdump -sass -arch "${arch}" "${object_dir}/${object}" |
                 extract_and_normalize "${pattern}")"
        if [ -z "${block}" ]; then
            echo "capture_sass.sh: ${name}: no kernel matching '${pattern}' in ${object}" >&2
            echo "The rung table and the built kernels disagree; fix the table rather " >&2
            echo "than committing an empty capture." >&2
            return 1
        fi
        body="${body}${block}"$'\n'
    done

    # A deterministic header. Nothing here varies between two builds of the same
    # source on the same toolkit: no timestamp, no commit, no host, no path. A
    # capture that carried any of those could not be diffed against a golden.
    #
    # The toolkit line is here because SASS is a function of the source, the
    # architecture and the assembler, and leaving the assembler out would let a
    # toolkit upgrade look like a kernel change. With it on the line, a mismatch
    # says what it is.
    printf '// rung: %s\n' "${name}"
    printf '// architecture: %s\n' "${arch}"
    printf '// toolkit: nvcc %s\n' "${toolkit}"
    printf '// source: cuobjdump -sass, normalized by benchmarks/capture_sass.sh rules 1 to 6\n'
    printf '//\n'
    printf '%s' "${body}"
}

selected=()
for entry in "${rungs[@]}"; do
    name="${entry%%|*}"
    if [ -z "${want_rung}" ] || [ "${name}" = "${want_rung}" ]; then
        selected+=("${entry}")
    fi
done

if [ "${#selected[@]}" -eq 0 ]; then
    echo "capture_sass.sh: no rung named '${want_rung}'. Run --list for the names." >&2
    exit 2
fi

if [ "${to_stdout}" -eq 1 ]; then
    if [ "${#selected[@]}" -ne 1 ]; then
        echo "capture_sass.sh: --stdout takes exactly one rung; pass --rung NAME." >&2
        exit 2
    fi
    entry="${selected[0]}"
    capture_one "${entry%%|*}" "${entry#*|}"
    exit 0
fi

mkdir -p "${out_dir}"
for entry in "${selected[@]}"; do
    name="${entry%%|*}"
    capture_one "${name}" "${entry#*|}" > "${out_dir}/${name}.sass"
    lines="$(grep -c '' "${out_dir}/${name}.sass")"
    echo "captured ${name}: ${lines} lines to ${out_dir}/${name}.sass"
done
